import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA code that fuses Instance Normalization and division by a constant
instance_norm_divide_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Kernel 1: Compute partial sums of input and input^2 for mean/variance
__global__ void compute_mean_var_kernel(const float* __restrict__ input,
                                        float* __restrict__ mean,
                                        float* __restrict__ var,
                                        int N, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H * W;
    if (idx >= total) return;

    float val = input[idx];
    int w = idx % W;
    int h = (idx / W) % H;
    int c = (idx / (W * H)) % C;
    int n = idx / (W * H * C);

    atomicAdd(&mean[n * C + c], val);
    atomicAdd(&var[n * C + c], val * val);
}

// Kernel 2: Finalize mean and variance (converts sums into actual mean/var)
__global__ void finalize_mean_var_kernel(float* __restrict__ mean,
                                         float* __restrict__ var,
                                         int N, int C, int H, int W,
                                         float eps) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C;
    if (idx >= total) return;

    float scale = 1.0f / (H * W);
    float m = mean[idx] * scale;
    float v = (var[idx] * scale) - (m * m); 
    if (v < 0.f) v = 0.f; // Numerical safeguard

    mean[idx] = m;
    var[idx]  = 1.0f / sqrtf(v + eps); // store inverse std
}

// Kernel 3: Apply Instance Norm + division
__global__ void instance_norm_divide_kernel(const float* __restrict__ input,
                                            float* __restrict__ output,
                                            const float* __restrict__ mean,
                                            const float* __restrict__ var,
                                            float divide_by,
                                            int N, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H * W;
    if (idx >= total) return;

    int w = idx % W;
    int h = (idx / W) % H;
    int c = (idx / (W * H)) % C;
    int n = idx / (W * H * C);

    float m = mean[n * C + c];
    float inv_std = var[n * C + c];
    float val = input[idx];

    // (x - mean) / std and then divide by constant
    val = (val - m) * inv_std;
    val /= divide_by;

    output[idx] = val;
}

torch::Tensor instance_norm_divide_cuda(torch::Tensor input, float eps, float divide_by) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);

    // Output tensor
    auto output = torch::zeros_like(input);

    // Tensors for mean and var per (N, C)
    auto mean = torch::zeros({N, C}, input.options());
    auto var  = torch::zeros({N, C}, input.options());

    int total = N * C * H * W;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    // Kernel 1: accumulate sums
    compute_mean_var_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        N, C, H, W
    );

    // Kernel 2: finalize mean, var
    int total_nc = N * C;
    grid_size = (total_nc + block_size - 1) / block_size;
    finalize_mean_var_kernel<<<grid_size, block_size>>>(
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        N, C, H, W,
        eps
    );

    // Kernel 3: apply instance norm + dividing
    grid_size = (total + block_size - 1) / block_size;
    instance_norm_divide_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        divide_by,
        N, C, H, W
    );

    return output;
}
"""

instance_norm_divide_cpp_source = r"""
torch::Tensor instance_norm_divide_cuda(torch::Tensor input, float eps, float divide_by);
"""

# Compile the inline CUDA code
instance_norm_divide = load_inline(
    name="instance_norm_divide",
    cpp_sources=instance_norm_divide_cpp_source,
    cuda_sources=instance_norm_divide_source,
    functions=["instance_norm_divide_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    """
    Optimized model: Convolution + fused Instance Normalization & divide.
    """
    def __init__(self, in_channels, out_channels, kernel_size, divide_by):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.eps = 1e-5
        self.divide_by = divide_by

    def forward(self, x):
        x = self.conv(x)
        x = instance_norm_divide.instance_norm_divide_cuda(x, self.eps, self.divide_by)
        return x

